def unpayable_totals(stamps, limit):
    can = [False] * (limit + 1)
    can[0] = True
    for total in range(1, limit + 1):
        for s in stamps:
            if s <= total and can[total - s]:
                can[total] = True
                break
    return can[1:].count(False)
